  "printed_units": [
    {
      "verse": 1,
      "source_text": "ቃለ፡ በረከት፡ ዘሄኖክ፡ በከመ፡ ባረከ፡ ኅሩያነ፡ ወጻድቃነ፡ እለ፡ ሀለዉ፡ ይኩኑ፡ በዕለተ፡\nምንዳቤ፡ ለ⟦?⟧ሲሎ፡ *ኵሎ፡ እኩያን፡ ወረሲዓን፡",
      "source_pages": [40],
      "critical_signs": ["*"],
      "uncertainties": [
        "Line 2, word 2: the printed span between initial ለ and ሲሎ is unresolved; its glyph segmentation is uncertain."
      ]
    },
    {
      "verse": 2,
      "source_text": "ወአንሥአ፡ *ወይቤ፡ ሄኖክ፡ ብእሲ፡ ጻድቅ፡ ዘእምነ፡ እግዚአብሔር፡ [እንዘ] አዕይን\nቲ፡ ክሡታት፡ ወይሬኢ፡ ራእየ፡ ቅዱሳነ፡ በሰማያት፡ ዘአርአየኒ፡ መላእክት፡ ወሰማዕኩ፡\nእምኔሆሙ፡ ኵሎ፡ *ወአስተውዓልኩ፡ አነ፡ †ዘ⟦?⟧ርአ⟦?⟧† ወአኮ፡ ለዝ፡ ትውልድ፡ አላ፡ ለዘ፡\nይመጽእ፡ ርሑቅ፡",
      "source_pages": [40],
