      ]
    },
    {
      "verse": 3,
      "source_text": "በእንተ፡ ኅሩያን፡ እቤ፡ ወአ⟦?⟧⟦?⟧እ፡ በእንቲአሆሙ፡ ምሳሌ፡\nይመጽእ፡ ቅዱስ፡ ወዐቢይ፡ እምኀደሩ፡",
      "source_pages": [40],
      "critical_signs": [],
